var appliedConfig string

func panicIfNoConfig() {
	configReloadCounter.WithLabelValues("failed").Inc()

	if RuntimeConfig.Badges == nil {
		panic("no config loaded")
	}

	if len(URLSafeSvgCache) == 0 {
		panic("no svg cache loaded")
	}
}

func fetchAndApplyRemoteConfig(u string) {
	// check if the remote config URL was already pointing to a file
	badgeAPIConfigFile := u
	var err error
	if !strings.HasSuffix(u, ".yaml") && !strings.HasSuffix(u, ".yml") {
		badgeAPIConfigFile, err = url.JoinPath(u, ".badge-api.yaml")
		if err != nil {
			slog.Error("could not join path", "err", err)
			panicIfNoConfig()
			return
		}
	} else {
		// remove the last part of the URL - we use it to later replace the <badge-config-repo> placeholder
		u = u[:strings.LastIndex(u, "/")]

	}

	// remove trailing slash from u
	u = strings.TrimSuffix(u, "/")

	slog.Info("fetching remote config", "URL", badgeAPIConfigFile) // #nosec G706 // False Positive: https://github.com/securego/gosec/issues/1622

	// get the matching git clients - those need to be defined even though we fetch the config from remote
	client, err := GetMatchingGitClient(badgeAPIConfigFile)
	if err != nil {
		slog.Error("could not find git client for remote config", "URL", u) // #nosec G706 // False Positive: https://github.com/securego/gosec/issues/1622
		panicIfNoConfig()
		return
	}

	// fetch the config
	content, err := client.GetFileFromRawURL(context.TODO(), badgeAPIConfigFile)
	if err != nil {
		slog.Error("could not fetch remote config", "err", err)
		panicIfNoConfig()
		return
	}

	handleYamlConfig(content, u)
}

func handleYamlConfig(content []byte, badgeConfigRepoURL string) {
	if string(content) == appliedConfig {
		slog.Info("remote config did not change")
		return
	}

	tempConfig := string(content)

	appliedConfig = strings.ReplaceAll(tempConfig, "<badge-config-repo>", badgeConfigRepoURL)

	// https://github.com/spf13/viper/issues/260 - viper does use only lowercase keys. Thats the way the runtime config type is defined. This does not match the yaml.Unmarshal behavior.
	// Therefore we need to convert the keys to lowercase - and then parse it as runtime config
	var m map[string]any
	// unmarshal the config
	var remoteConfig RuntimeConfigType
	err := yaml.Unmarshal([]byte(appliedConfig), &m)
